//! CAS cross-validation integration test for F_5 and F_7 permanents.
//!
//! Reads [`data/cas_permanent_f5_f7.csv`] — a CSV of 1000 test vectors
//! generated by `scripts/generate-cas-permanent-vectors.sage` using
//! SageMath's built-in `Matrix.permanent()` as the canonical second opinion
//! (issue `333028c1`, criterion 1–4).
//!
//! Each data row contains:
//!   - `q`  — prime (5 or 7)
//!   - `n`  — matrix dimension (one of 4, 6, 8, 10, 12)
//!   - `matrix` — row-major entries, space-separated, rows joined by " / "
//!   - `expected_permanent` — integer in `[0, q)`, CAS-computed
//!
//! The test verifies that our packed Ryser implementations
//! ([`permanent_bipedal5`] and [`permanent_bipedal7`]) produce the same
//! permanent as SageMath's general-purpose algorithm on every vector.
//!
//! # Coverage
//!
//! 5 cell sizes × 2 prime fields × 100 vectors = 1000 vectors total.
//! All vectors are in the fast-tier (no `#[ignore]`): the largest
//! matrices are 12 × 12, requiring 2^12 − 1 = 4095 Gray-code steps each;
//! 500 such matrices (q = 5 or q = 7) run well under 5 s in release mode.
//!
//! # RNG
//!
//! The CSV was generated with Python's `random` module seeded with the
//! string `"0xc0ffee0000000000"` (embedded in the CSV header). Re-running
//! the Sage script with the same seed yields a bit-identical CSV.

#[cfg(all(feature = "f5", feature = "f7"))]
mod tests {
    use gf2_algebra::packed::{Packed5Matrix, Packed7Matrix};
    use gf2_algebra::permanent::{permanent_bipedal5, permanent_bipedal7};
    use gf2_core::gfp::Fp;

    /// Parse the CAS CSV and return `(q, n, row_major_entries, expected)` for
    /// every data row (non-comment, non-header lines).
    ///
    /// # Arguments
    ///
    /// * `csv` — the full CSV text (from `include_str!`).
    ///
    /// # Returns
    ///
    /// A `Vec` of `(u64, usize, Vec<u64>, u64)` tuples:
    ///   - `q` — prime field characteristic (5 or 7)
    ///   - `n` — matrix dimension
    ///   - `entries` — `n * n` row-major integer entries in `[0, q)`
    ///   - `expected` — CAS-computed permanent in `[0, q)`
    fn parse_csv(csv: &str) -> Vec<(u64, usize, Vec<u64>, u64)> {
        let mut rows = Vec::new();
        for line in csv.lines() {
            // Skip comment lines and the header line.
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') || line.starts_with("q,") {
                continue;
            }
            // Format: q,n,"matrix_string",expected_permanent
            // The matrix_string may be quoted (CSV quoting for strings with '/').
            // Split on commas, but the matrix field uses '/' internally (not commas),
            // so a simple split on ',' works if we reconstruct carefully.
            // CSV rows look like: 5,4,2 4 4 4 / 0 0 2 1 / 0 3 2 2 / 3 3 2 2,2
            // The matrix field contains spaces and '/' but never commas, so
            // a naive split-on-comma with the first two and last fields works.
            let parts: Vec<&str> = line.splitn(4, ',').collect();
            assert_eq!(
                parts.len(),
                4,
                "CSV line malformed (expected 4 comma-separated fields): {line:?}"
            );
            let q: u64 = parts[0].trim().parse().expect("q must be an integer");
            let n: usize = parts[1].trim().parse().expect("n must be an integer");
            // parts[2] is "matrix_field,expected" where matrix_field is the
            // 3rd column — but because we used splitn(4), parts[2] is the
            // matrix and parts[3] is the expected.
            let mat_str = parts[2].trim().trim_matches('"');
            let expected: u64 = parts[3]
                .trim()
                .trim_matches('"')
                .parse()
                .expect("expected_permanent must be an integer");

            // Parse row-major entries: rows separated by " / ", entries by " ".
            let mut entries = Vec::with_capacity(n * n);
            for row_str in mat_str.split(" / ") {
                for tok in row_str.split_whitespace() {
                    let v: u64 = tok.parse().expect("matrix entry must be an integer");
                    entries.push(v);
                }
            }
            assert_eq!(
                entries.len(),
                n * n,
                "CSV row has wrong number of matrix entries: expected {}, got {}; line={line:?}",
                n * n,
                entries.len()
            );

            rows.push((q, n, entries, expected));
        }
        rows
    }

    /// CAS cross-validation for F_5 (`permanent_bipedal5`).
    ///
    /// Reads all rows with `q = 5` from the committed CSV and verifies that
    /// `permanent_bipedal5` matches the SageMath-computed permanent on every
    /// vector bit-for-bit.
    ///
    /// # Arguments
    ///
    /// None — the CSV is embedded at compile time via `include_str!`.
    ///
    /// # Examples
    ///
    /// Run as part of the fast-tier CI gate:
    ///
    /// ```text
    /// cargo nextest run -p gf2-algebra --release --profile ci --all-features
    /// ```
    ///
    /// # Panics
    ///
    /// Panics on the first mismatch, reporting `q`, `n`, the row index,
    /// and both the computed and expected permanents.
    ///
    /// # Complexity
    ///
    /// `O(500 * n * 2^n)` — 500 F_5 vectors, each up to 12 × 12.
    /// Largest single call: `n = 12`, `2^12 = 4096` Gray steps.
    #[test]
    fn cas_cross_validation_f5() {
        let csv = include_str!("data/cas_permanent_f5_f7.csv");
        let rows = parse_csv(csv);
        let f5_rows: Vec<_> = rows.iter().filter(|(q, _, _, _)| *q == 5).collect();
        assert!(
            !f5_rows.is_empty(),
            "cas_permanent_f5_f7.csv contains no F_5 rows"
        );
        for (idx, (q, n, entries, expected)) in f5_rows.iter().enumerate() {
            let mat_entries: Vec<Fp<5>> = entries.iter().map(|&v| Fp::<5>::new(v)).collect();
            let mat = Packed5Matrix::from_row_major(&mat_entries, *n, *n);
            let got = permanent_bipedal5(&mat);
            let exp = Fp::<5>::new(*expected);
            assert_eq!(
                got,
                exp,
                "F_5 CAS mismatch: q={q}, n={n}, row_index={idx}, \
                 computed={}, expected={}",
                got.value(),
                exp.value(),
            );
        }
    }

    /// CAS cross-validation for F_7 (`permanent_bipedal7`).
    ///
    /// Reads all rows with `q = 7` from the committed CSV and verifies that
    /// `permanent_bipedal7` matches the SageMath-computed permanent on every
    /// vector bit-for-bit.
    ///
    /// # Arguments
    ///
    /// None — the CSV is embedded at compile time via `include_str!`.
    ///
    /// # Examples
    ///
    /// Run as part of the fast-tier CI gate:
    ///
    /// ```text
    /// cargo nextest run -p gf2-algebra --release --profile ci --all-features
    /// ```
    ///
    /// # Panics
    ///
    /// Panics on the first mismatch, reporting `q`, `n`, the row index,
    /// and both the computed and expected permanents.
    ///
    /// # Complexity
    ///
    /// `O(500 * n * 2^n)` — 500 F_7 vectors, each up to 12 × 12.
    /// Largest single call: `n = 12`, `2^12 = 4096` Gray steps.
    #[test]
    fn cas_cross_validation_f7() {
        let csv = include_str!("data/cas_permanent_f5_f7.csv");
        let rows = parse_csv(csv);
        let f7_rows: Vec<_> = rows.iter().filter(|(q, _, _, _)| *q == 7).collect();
        assert!(
            !f7_rows.is_empty(),
            "cas_permanent_f5_f7.csv contains no F_7 rows"
        );
        for (idx, (q, n, entries, expected)) in f7_rows.iter().enumerate() {
            let mat_entries: Vec<Fp<7>> = entries.iter().map(|&v| Fp::<7>::new(v)).collect();
            let mat = Packed7Matrix::from_row_major(&mat_entries, *n, *n);
            let got = permanent_bipedal7(&mat);
            let exp = Fp::<7>::new(*expected);
            assert_eq!(
                got,
                exp,
                "F_7 CAS mismatch: q={q}, n={n}, row_index={idx}, \
                 computed={}, expected={}",
                got.value(),
                exp.value(),
            );
        }
    }
}
